1	package org.springframework.samples.petclinic.model;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Single source of truth for an owner's {@code customerCode} and the values derived from it.
9	 *
10	 * <p>The code has the shape {@code <REGION>-<HASH8>}: {@code REGION} is the region code derived from
11	 * the postcode and {@code HASH8} is the first 8 upper-case hex characters of
12	 * {@code SHA-256(normalizedTelephone + lastName)} (see {@link #hash8(String, String)}). The format is
13	 * assembled by {@link #format(String, String)} and read back by {@link #region(String)}; both sit here
14	 * so the separator and ordering live as one matched pair. Sequence numbers are no longer part of the
15	 * identity.
16	 *
17	 * <p>The {@link #checkDigit(String)} rule computes the standard Luhn check digit over the digits
18	 * contained in the code (non-digit characters, such as the formatting dash, are ignored). It is the
19	 * single source of truth for the {@code checkDigit} response field exposed by {@code OwnerMapper}.
20	 */
21	public final class CustomerCode {
22	
23	    /** The single character separating the {@code REGION} and {@code HASH8} components. */
24	    private static final char SEPARATOR = '-';
25	
26	    /** The region string used when a postcode (or a stored code) resolves to no known region. The
27	     *  canonical definition of this sentinel, which {@code Regions.UNKNOWN} also points at so the
28	     *  region a code is built with and the region read back out can never diverge. */
29	    public static final String UNKNOWN_REGION = "UNKNOWN";
30	
31	    private CustomerCode() {
32	    }
33	
34	    /**
35	     * Assemble a {@code <REGION>-<HASH8>} customer code from its components. The exact inverse of
36	     * {@link #region(String)}: both use the one {@link #SEPARATOR} defined here, so the producing and
37	     * parsing sides cannot drift apart.
38	     *
39	     * @param region the region code (typically {@code Regions.regionForPostcode(...)})
40	     * @param hash8  the 8-character hash component (see {@link #hash8(String, String)})
41	     * @return the assembled customer code
42	     */
43	    public static String format(String region, String hash8) {
44	        return region + SEPARATOR + hash8;
45	    }
46	
47	    /**
48	     * Spell a de-duplicated customer code by appending a numeric suffix to {@code base}, joined with the
49	     * same {@link #SEPARATOR} as {@link #format(String, String)} so the dedup suffix cannot drift from
50	     * the region/hash separator. Used when a computed code collides with an existing owner's: callers try
51	     * {@code n} of 2, 3, ... until the result is unique (e.g. {@code NSW-1A2B3C4D-2}).
52	     *
53	     * @param base the colliding base code to disambiguate
54	     * @param n    the suffix number (2 or more)
55	     * @return {@code base}, the separator and {@code n}
56	     */
57	    public static String withSuffix(String base, int n) {
58	        return base + SEPARATOR + n;
59	    }
60	
61	    /**
62	     * Compute the {@code HASH8} component: the first 8 upper-case hex characters of
63	     * {@code SHA-256(normalizedTelephone + lastName)}, where the telephone is normalized to E.164 form
64	     * (see {@link OwnerTelephone#toE164(String)}) exactly as the owner's identity key is, so the hash
65	     * over a submitted and a stored owner can never silently diverge.
66	     *
67	     * @param telephone the owner's telephone; normalized to E.164 before hashing
68	     * @param lastName  the owner's last name
69	     * @return the 8 upper-case hex characters
70	     */
71	    public static String hash8(String telephone, String lastName) {
72	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
73	        if (normalizedTelephone == null) {
74	            normalizedTelephone = telephone == null ? "" : telephone;
75	        }
76	        String last = lastName == null ? "" : lastName;
77	        return sha256UpperHex(normalizedTelephone + last).substring(0, 8);
78	    }
79	
80	    /**
81	     * Read the {@code REGION} component back out of a {@code <REGION>-<HASH8>} customer code; the exact
82	     * inverse of {@link #format(String, String)}. This is the single source of truth for the
83	     * {@code locality} response field, so the locality an owner reports is exactly the region baked into
84	     * its identity.
85	     *
86	     * @param code the customer code; may be {@code null}
87	     * @return the region prefix, or {@link #UNKNOWN_REGION} when the code is {@code null} or has no dash
88	     */
89	    public static String region(String code) {
90	        if (code == null) {
91	            return UNKNOWN_REGION;
92	        }
93	        int dash = code.indexOf(SEPARATOR);
94	        return dash < 0 ? code : code.substring(0, dash);
95	    }
96	
97	    /**
98	     * Compute the Luhn check digit over the digits contained in {@code code}.
99	     *
100	     * @param code the customer code; non-digit characters are ignored
101	     * @return the Luhn check digit, between 0 and 9 inclusive
102	     */
103	    public static int checkDigit(String code) {
104	        int sum = 0;
105	        boolean dbl = true;
106	        for (int i = code.length() - 1; i >= 0; i--) {
107	            char c = code.charAt(i);
108	            if (c < '0' || c > '9') {
109	                continue;
110	            }
111	            int d = c - '0';
112	            if (dbl) {
113	                d *= 2;
114	                if (d > 9) {
115	                    d -= 9;
116	                }
117	            }
118	            sum += d;
119	            dbl = !dbl;
120	        }
121	        return (10 - (sum % 10)) % 10;
122	    }
123	
124	    /** Full upper-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
125	    private static String sha256UpperHex(String s) {
126	        try {
127	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
128	            StringBuilder sb = new StringBuilder(digest.length * 2);
129	            for (byte b : digest) {
130	                sb.append(String.format("%02X", b));
131	            }
132	            return sb.toString();
133	        }
134	        catch (NoSuchAlgorithmException ex) {
135	            throw new IllegalStateException("SHA-256 not available", ex);
136	        }
137	    }
138	}
