1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Single source of truth for an owner's fiscal-year derivations. The fiscal year starts on 1 July: a
8	 * date on or after 1 July belongs to the fiscal year that started that calendar year, an earlier date
9	 * to the one that started the previous calendar year. A fiscal year is identified by the calendar year
10	 * it starts in, so the fiscal year running 1 July 2026 - 30 June 2027 is year 2026 and labelled
11	 * {@code FY26}.
12	 *
13	 * <p>This is a model-level derivation of an {@link Owner} (like {@link MembershipNumber} and
14	 * {@link MembershipLevel}): it is consumed by the response mapper (the {@code fiscalYear} field) and by
15	 * the other date-derived values that moved to a fiscal-year basis - the membership number's year
16	 * segment ({@link MembershipNumber}) and tenure ({@link MembershipLevel}) - so it lives in the model
17	 * layer rather than beside the pipeline functions.
18	 *
19	 * <p>Every value is computed from the owner's stored registration date, which the create pipeline has
20	 * already rolled forward to a business day, so these derivations are on a business-day-adjusted basis.
21	 */
22	public final class FiscalYear {
23	
24	    /** The month a fiscal year starts on (1 July). */
25	    public static final Month START_MONTH = Month.JULY;
26	
27	    private FiscalYear() {
28	    }
29	
30	    /**
31	     * The fiscal year a date falls in, identified by the calendar year the fiscal year starts in. A
32	     * date on or after 1 July yields its own calendar year; an earlier date yields the previous one.
33	     */
34	    public static int startYearOf(LocalDate date) {
35	        return date.getMonthValue() >= START_MONTH.getValue() ? date.getYear() : date.getYear() - 1;
36	    }
37	
38	    /** The {@code fiscalYear} label {@code FY<YY>} of an owner, from its registration date. */
39	    public static String of(Owner owner) {
40	        return label(owner.getRegistrationDate());
41	    }
42	
43	    /**
44	     * The two-digit fiscal-year start year ({@code YY}) for a date, zero-padded. The single rendering
45	     * of the fiscal year's two digits, shared by this class's {@link #label(LocalDate)} and by the
46	     * {@link MembershipNumber} year segment, so the two cannot drift apart.
47	     */
48	    public static String twoDigitStartYear(LocalDate date) {
49	        return String.format("%02d", startYearOf(date) % 100);
50	    }
51	
52	    /** The {@code FY<YY>} label for a date, where {@code YY} is the two-digit fiscal-year start year. */
53	    private static String label(LocalDate date) {
54	        return "FY" + twoDigitStartYear(date);
55	    }
56	}
