3	/**
4	 * Single source of truth for an owner's <em>primary identifier</em>: the one human-facing value that
5	 * uniquely names the owner in external records and events. Today that is the {@link Owner#getCustomerCode()
6	 * customerCode}; when the customer code is later unified into the member id, this method changes to return
7	 * the member id and every consumer (such as the {@code OWNER_CREATED} audit event) follows automatically.
8	 *
9	 * <p>This is a model-level derivation of an {@link Owner} (like {@link MembershipNumber} and
10	 * {@link OwnerIdentity}): it exists so callers never hard-code which field is the primary identifier.
11	 */
12	public final class OwnerPrimaryIdentifier {
13	
14	    private OwnerPrimaryIdentifier() {
15	    }
16	
17	    /** The current primary identifier of a persisted or in-flight owner. */
18	    public static String of(Owner owner) {
19	        return owner.getCustomerCode();
20	    }
21	}
