1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.CustomerCode;
6	
7	/**
8	 * City-to-region lookup backing the {@code locality} field produced by
9	 * {@link OwnerMapper#toOwnerDto}. The table pins each known city to its canonical region string; any
10	 * city not listed derives the locality {@code "UNKNOWN"}.
11	 */
12	public final class Regions {
13	
14	    /** City -> canonical region. Anything not listed derives locality {@link #UNKNOWN}. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	        "Sydney", "NSW",
17	        "Melbourne", "VIC",
18	        "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. A region absent from this table (and
21	     *  the {@link #UNKNOWN} locality) imposes no postcode range. */
22	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
23	        "NSW", new int[] {2000, 2099},
24	        "VIC", new int[] {3000, 3099},
25	        "QLD", new int[] {4000, 4099});
26	
27	    /** Region -> IANA timezone name. A region absent from this table (including the {@link #UNKNOWN}
28	     *  locality) has no known timezone. */
29	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
30	        "NSW", "Australia/Sydney",
31	        "VIC", "Australia/Melbourne",
32	        "QLD", "Australia/Brisbane");
33	
34	    /** The locality returned for a city absent from {@link #CITY_REGION}. Points at the single
35	     *  {@link CustomerCode#UNKNOWN_REGION} definition so the region baked into a customer code and the
36	     *  region/locality derived here share one sentinel. */
37	    public static final String UNKNOWN = CustomerCode.UNKNOWN_REGION;
38	
39	    private Regions() {
40	    }
41	
42	    /**
43	     * Whether a 4-digit postcode is valid for the given city. A city whose region has no pinned
44	     * postcode range (including an unknown city) accepts any value.
45	     *
46	     * @param city     the owner's city; may be {@code null}
47	     * @param postcode the already-4-digit postcode to check
48	     * @return {@code true} when the city's region imposes no range or the postcode falls within it
49	     */
50	    public static boolean postcodeMatchesCity(String city, String postcode) {
51	        int[] range = REGION_POSTCODES.get(localityOf(city));
52	        if (range == null) {
53	            return true;
54	        }
55	        int value = Integer.parseInt(postcode);
56	        return value >= range[0] && value <= range[1];
57	    }
58	
59	    /**
60	     * Derive the locality (canonical region) preferring the postcode. The postcode's region range is
61	     * consulted first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when the postcode is absent
62	     * or falls in no known range does the city-to-region table decide. This returns the same region
63	     * for known cities but disambiguates cities that share a name.
64	     *
65	     * @param city     the owner's city; may be {@code null}
66	     * @param postcode the owner's postcode; may be {@code null}
67	     * @return the canonical region string, or {@code "UNKNOWN"} when neither postcode nor city resolves
68	     */
69	    public static String localityOf(String city, String postcode) {
70	        String byPostcode = regionOfPostcode(postcode);
71	        return byPostcode != null ? byPostcode : localityOf(city);
72	    }
73	
74	    /**
75	     * Derive the region code purely from the postcode. This is the {@code REGION} component of an
76	     * owner's {@code <REGION>-<HASH8>} customer code: the region whose range contains the postcode, or
77	     * {@link #UNKNOWN} when the postcode is absent, non-numeric, or falls in no known range. Unlike
78	     * {@link #localityOf(String, String)} it never falls back to the city.
79	     *
80	     * @param postcode the owner's postcode; may be {@code null}
81	     * @return the canonical region string, or {@code "UNKNOWN"} when the postcode resolves to no region
82	     */
83	    public static String regionForPostcode(String postcode) {
84	        String region = regionOfPostcode(postcode);
85	        return region != null ? region : UNKNOWN;
86	    }
87	
88	    /**
89	     * Derive the locality (canonical region) for a city.
90	     *
91	     * @param city the owner's city; may be {@code null}
92	     * @return the canonical region string, or {@code "UNKNOWN"} when the city is not in the table
93	     */
94	    public static String localityOf(String city) {
95	        return CITY_REGION.getOrDefault(city, UNKNOWN);
96	    }
97	
98	    /**
99	     * Whether {@code region} is a known, pinned region (NSW, VIC or QLD) rather than the
100	     * {@link #UNKNOWN} sentinel or some other value. Backed by the same {@link #REGION_TIMEZONE}
101	     * table the other region facts are derived from, so the set of known regions stays single-sourced
102	     * here and cannot drift from a copy held elsewhere.
103	     *
104	     * @param region the canonical region code (e.g. an owner's {@code locality}); may be {@code null}
105	     * @return {@code true} when {@code region} is one of the pinned regions
106	     */
107	    public static boolean isKnownRegion(String region) {
108	        return REGION_TIMEZONE.containsKey(region);
109	    }
110	
111	    /**
112	     * The IANA timezone name for a region, taken from the pinned region-to-timezone table
113	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane).
114	     *
115	     * @param region the canonical region code (e.g. the owner's {@code locality}); may be {@code null}
116	     * @return the IANA timezone name, or {@code null} when the region has no pinned timezone
117	     */
118	    public static String timezoneOf(String region) {
119	        return REGION_TIMEZONE.get(region);
120	    }
121	
122	    /**
123	     * The region whose postcode range contains the given postcode, or {@code null} when the postcode
124	     * is absent, non-numeric, or falls in no known range.
125	     */
126	    private static String regionOfPostcode(String postcode) {
127	        if (postcode == null) {
128	            return null;
129	        }
130	        int value;
131	        try {
132	            value = Integer.parseInt(postcode.trim());
133	        }
134	        catch (NumberFormatException ex) {
135	            return null;
136	        }
137	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
138	            int[] range = entry.getValue();
139	            if (value >= range[0] && value <= range[1]) {
140	                return entry.getKey();
141	            }
142	        }
143	        return null;
144	    }
145	}
