1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.CustomerCode;
4	import org.springframework.samples.petclinic.model.MembershipLevel;
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives the {@code ownerSegment} field produced by {@link OwnerMapper#toOwnerDto}: a coarse
9	 * marketing segment formatted {@code <TIER>_<AREA>}, one of {@code PREMIUM_METRO},
10	 * {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
11	 *
12	 * <p>{@code TIER} is {@code PREMIUM} when the owner's {@link MembershipLevel#of(Owner) membership
13	 * level} is {@link #PREMIUM_FROM} (3) or more, otherwise {@code STANDARD}. {@code AREA} is
14	 * {@code METRO} when the owner's {@link CustomerCode#region(String) locality} is a
15	 * {@link Regions#isKnownRegion(String) known region} (NSW, VIC or QLD), otherwise {@code REGIONAL}.
16	 */
17	public final class OwnerSegment {
18	
19	    /** Minimum membership level (inclusive) for the {@code PREMIUM} tier; below this is STANDARD. */
20	    private static final int PREMIUM_FROM = 3;
21	
22	    private OwnerSegment() {
23	    }
24	
25	    /**
26	     * Derive the segment for an owner.
27	     *
28	     * @param owner the owner; its membership level and locality drive the result
29	     * @return the segment, formatted {@code <TIER>_<AREA>}
30	     */
31	    public static String of(Owner owner) {
32	        String tier = MembershipLevel.of(owner) >= PREMIUM_FROM ? "PREMIUM" : "STANDARD";
33	        String locality = CustomerCode.region(owner.getCustomerCode());
34	        String area = Regions.isKnownRegion(locality) ? "METRO" : "REGIONAL";
35	        return tier + "_" + area;
36	    }
37	}
