1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import tools.jackson.databind.ObjectMapper;
10	import tools.jackson.databind.json.JsonMapper;
11	import org.springframework.samples.petclinic.model.MembershipLevel;
12	import org.springframework.samples.petclinic.model.MembershipNumber;
13	import org.springframework.samples.petclinic.model.Owner;
14	import org.springframework.samples.petclinic.model.OwnerPrimaryIdentifier;
15	
16	/**
17	 * Runs after {@link SaveOwner} on {@code POST /api/owners}, once the owner has been persisted and
18	 * assigned an id. Emits the human-readable audit line via the dedicated {@code AUDIT} logger, and then
19	 * an immutable structured {@link OwnerCreatedEvent} serialized to JSON on the same logger. The event
20	 * carries a process-wide monotonically increasing {@code seq}, the owner id and the owner's current
21	 * {@link OwnerPrimaryIdentifier primary identifier} (the customerCode today, the member id once unified).
22	 */
23	public class AuditOwnerCreated {
24	
25	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
26	
27	    private static final ObjectMapper MAPPER = JsonMapper.builder().build();
28	
29	    /** Monotonically increasing sequence across all owner creates in this process. */
30	    private static final AtomicLong SEQ = new AtomicLong();
31	
32	    public void service(@Val Owner owner) {
33	        AUDIT.info(
34	                "Created owner id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
35	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
36	                MembershipLevel.of(owner), MembershipNumber.of(owner));
37	
38	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
39	                OwnerPrimaryIdentifier.of(owner), MembershipLevel.of(owner));
40	        AUDIT.info(MAPPER.writeValueAsString(event));
41	    }
42	}
