6	import java.util.Set;
7	import java.util.regex.Pattern;
8	
9	import net.officefloor.plugin.variable.Out;
10	import org.springframework.samples.petclinic.mapper.Regions;
11	import org.springframework.samples.petclinic.model.OwnerTelephone;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailDisposableException;
14	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;
15	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsMissingException;
16	import org.springframework.samples.petclinic.rest.escalation.OwnerPostcodeInvalidException;
17	import org.springframework.samples.petclinic.rest.escalation.OwnerRegistrationDateFutureException;
18	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
19	import org.springframework.web.bind.annotation.RequestBody;
20	
21	/**
22	 * First step of {@code POST /api/owners} and the single step that binds the request body. Rejects a
23	 * body that is missing or blank in any required field (firstName, lastName, address, city, telephone)
24	 * with a 400 whose {@code errors} array lists the offending field names. A whitespace-only value is
25	 * treated as blank — the DTO's {@code @Size(min = 1)} alone would accept it — so this check, not bean
26	 * validation, is the authoritative implementation of the required-field rule.
27	 *
28	 * <p>The address is normalized (see {@link OwnerAddress}) before the required-field check, so an
29	 * address that is blank once whitespace is collapsed is rejected as missing. The normalized value is
30	 * written back onto the body so the normalized, abbreviation-expanded address is what gets stored,
31	 * returned and compared for household matching.
32	 *
33	 * <p>The telephone is then converted to E.164 form (see {@link OwnerTelephone#toE164(String)}); a
34	 * value that cannot form a valid E.164 number is rejected with a 400 via
35	 * {@link OwnerTelephoneInvalidException}. The E.164 value is written back onto the body so it is what
36	 * gets stored and returned.
37	 *
38	 * <p>Email is optional. When absent (null) it is left untouched. When present it must be a
39	 * syntactically valid address; otherwise the create is rejected with a 400 via
40	 * {@link OwnerEmailInvalidException}. A syntactically valid email whose domain is on the
41	 * disposable-domain blocklist is rejected with a 400 via {@link OwnerEmailDisposableException}. A
42	 * valid, accepted email is lower-cased and written back onto the body so the lower-cased value is
43	 * what gets stored and returned. The validated body is republished for {@link BuildOwner}.
44	 */
45	public class ValidateOwner {
46	
47	    /** Pragmatic syntactic check: non-empty local part, '@', non-empty domain containing a dot. */
48	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
49	
50	    /** Disposable email domains that are refused; compared case-insensitively. */
51	    private static final Set<String> DISPOSABLE_DOMAINS =
52	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
53	
54	    /** A postcode is a string of exactly four digits. */
55	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
56	
57	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
58	            throws OwnerFieldsMissingException, OwnerTelephoneInvalidException,
59	            OwnerEmailInvalidException, OwnerEmailDisposableException,
60	            OwnerPostcodeInvalidException, OwnerRegistrationDateFutureException {
61	        List<String> missing = new ArrayList<>();
62	        if (isBlank(request.getFirstName())) {
63	            missing.add("firstName");
64	        }
65	        if (isBlank(request.getLastName())) {
66	            missing.add("lastName");
67	        }
68	        // Address may be supplied in structured form (addressLine1 [+ addressLine2]) or as the flat
69	        // 'address' field. Structured fields take precedence when present. Normalization (see
70	        // OwnerAddress) applies to whichever fields are supplied; the composed, normalized value is
71	        // written back onto the flat 'address' so it is what gets stored, returned and read by
72	        // everything downstream.
73	        String addressLine1 = OwnerAddress.normalize(request.getAddressLine1());
74	        String addressLine2 = OwnerAddress.normalize(request.getAddressLine2());
75	        boolean structured = !addressLine1.isEmpty();
76	        String address = structured
77	                ? OwnerAddress.compose(addressLine1, addressLine2)
78	                : OwnerAddress.normalize(request.getAddress());
79	        if (address.isEmpty()) {
80	            missing.add("address");
81	        }
82	        if (isBlank(request.getCity())) {
83	            missing.add("city");
84	        }
85	        if (isBlank(request.getTelephone())) {
86	            missing.add("telephone");
87	        }
88	        if (!missing.isEmpty()) {
89	            throw new OwnerFieldsMissingException(missing);
90	        }
91	        request.setAddress(address);
92	        if (structured) {
93	            request.setAddressLine1(addressLine1);
94	            request.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
95	        }
96	        String e164 = OwnerTelephone.toE164(request.getTelephone());
97	        if (e164 == null) {
98	            throw new OwnerTelephoneInvalidException(request.getTelephone());
99	        }
100	        request.setTelephone(e164);
101	
102	        String email = request.getEmail();
103	        if (email != null) {
104	            if (!EMAIL.matcher(email).matches()) {
105	                throw new OwnerEmailInvalidException(email);
106	            }
107	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase();
108	            if (DISPOSABLE_DOMAINS.contains(domain)) {
109	                throw new OwnerEmailDisposableException(domain);
110	            }
111	            request.setEmail(email.toLowerCase());
112	        }
113	
114	        // Postcode is optional. When present it must be a 4-digit value that is valid for the
115	        // owner's city region; a city with no known region accepts any 4-digit value.
116	        String postcode = request.getPostcode();
117	        if (postcode != null) {
118	            if (!POSTCODE.matcher(postcode).matches()
119	                    || !Regions.postcodeMatchesCity(request.getCity(), postcode)) {
120	                throw new OwnerPostcodeInvalidException(postcode);
121	            }
122	        }
123	
124	        // Registration may be supplied but never dated in the future: a value later than the
125	        // server's current date is rejected with a 400.
126	        LocalDate registrationDate = request.getRegistrationDate();
127	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
128	            throw new OwnerRegistrationDateFutureException(registrationDate);
129	        }
130	
131	        validated.set(request);
132	    }
133	
134	    private static boolean isBlank(String value) {
135	        return value == null || value.isBlank();
136	    }
137	}
