    }

    /**
     * The region whose postcode range contains the given postcode, or {@code null} when the postcode
     * is absent, non-numeric, or falls in no known range.
     */
    private static String regionOfPostcode(String postcode) {
        if (postcode == null) {
            return null;
        }
        int value;
