12	/**
13	 * Runs after {@link BuildOwner} and before {@link SaveOwner} on {@code POST /api/owners}. Assigns the
14	 * new owner's {@code customerCode} formatted {@code <REGION>-<HASH8>}, where REGION is the region code
15	 * derived from the postcode (see {@link Regions#regionForPostcode(String)}, e.g. {@code NSW}, or
16	 * {@code UNKNOWN} when the postcode resolves to no known region) and HASH8 is the first 8 upper-case
17	 * hex characters of {@code SHA-256(normalizedTelephone + lastName)} (see
18	 * {@link CustomerCode#hash8(String, String)}, e.g. {@code NSW-1A2B3C4D}). The identity no longer uses
19	 * per-city sequence numbers, so this step depends only on the owner's own fields.
20	 *
21	 * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is
22	 * appended with the smallest {@code n} of 2 or more that makes it unique (e.g. {@code NSW-1A2B3C4D-2}),
23	 * so distinct owners always get distinct customer codes. The new owner is still unsaved, so it is not
24	 * among the owners compared against here and cannot collide with itself.
25	 */
26	public class AssignCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = Regions.regionForPostcode(owner.getPostcode());
30	        String hash8 = CustomerCode.hash8(owner.getTelephone(), owner.getLastName());
31	        String base = CustomerCode.format(region, hash8);
32	
33	        Set<String> existing = new HashSet<>();
34	        for (Owner other : ownerRepository.findAll()) {
35	            String code = other.getCustomerCode();
36	            if (code != null) {
37	                existing.add(code);
38	            }
39	        }
40	
41	        String code = base;
42	        for (int n = 2; existing.contains(code); n++) {
43	            code = CustomerCode.withSuffix(base, n);
44	        }
45	        owner.setCustomerCode(code);
46	    }
47	}
